# api/middleware.py - Custom middleware for Django REST API
import re
from django.http import HttpResponse, HttpResponseBadRequest
from django.utils.deprecation import MiddlewareMixin


class TransferEncodingMiddleware(MiddlewareMixin):
    """
    Middleware to handle chunked transfer encoding for legacy client compatibility.
    Some older clients send both Content-Length and Transfer-Encoding headers.
    We normalize the request before passing to Django's request handler.
    """

    def process_request(self, request):
        # Log raw headers for debugging
        te_header = request.META.get('HTTP_TRANSFER_ENCODING', '')
        cl_header = request.META.get('CONTENT_LENGTH', '')

        # Allow both headers to coexist for backward compatibility
        # RFC 7230 says TE takes precedence, but we keep CL for logging
        if te_header and cl_header:
            request._raw_content_length = cl_header
            # Don't strip Content-Length - some downstream services need it
            pass

        return None


class RequestRoutingMiddleware(MiddlewareMixin):
    """
    Routes requests to appropriate backend based on X-Service-Route header.
    Used in microservice architecture for internal request forwarding.
    """

    ALLOWED_BACKENDS = {
        'billing': 'http://billing-service.internal:8080',
        'inventory': 'http://inventory-service.internal:8081',
        'auth': 'http://auth-service.internal:8082',
    }

    def process_request(self, request):
        route = request.META.get('HTTP_X_SERVICE_ROUTE', '')
        if route and route in self.ALLOWED_BACKENDS:
            request._backend_url = self.ALLOWED_BACKENDS[route]
        return None


