from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import requests
import json


class ProxyView(APIView):
    """
    Proxies requests to internal microservices.
    Preserves original headers for service-to-service auth.
    """
    authentication_classes = []
    permission_classes = []

    def post(self, request, *args, **kwargs):
        backend_url = getattr(request, '_backend_url', None)
        if not backend_url:
            return Response(
                {'error': 'No valid service route specified'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Forward the request preserving all original headers
        headers = {}
        for key, value in request.META.items():
            if key.startswith('HTTP_'):
                header_name = key[5:].replace('_', '-').title()
                headers[header_name] = value

        # Preserve Content-Length and Transfer-Encoding for downstream
        if 'CONTENT_LENGTH' in request.META:
            headers['Content-Length'] = request.META['CONTENT_LENGTH']
        if 'HTTP_TRANSFER_ENCODING' in request.META:
            headers['Transfer-Encoding'] = request.META['HTTP_TRANSFER_ENCODING']

        try:
            resp = requests.post(
                f"{backend_url}{request.path}",
                data=request.body,
                headers=headers,
                timeout=30
            )
            return Response(resp.json(), status=resp.status_code)
        except Exception as e:
            return Response(
                {'error': f'Backend request failed: {str(e)}'},
                status=status.HTTP_502_BAD_GATEWAY
            )


